choose.when:
select date_format(create_time, '%H:00') as date, count(*) as requestCount, ifnull(sum(total_tokens), 0) as totalTokens, ifnull(sum(cost), 0) as cost from ai_log where create_time >= curdate() and create_time < date_add(curdate(), interval 1 day)
and user_id = #{userId}
group by date_format(create_time, '%H:00') order by date asc

choose.otherwise:
select date_format(create_time, '%Y-%m-%d') as date, count(*) as requestCount, ifnull(sum(total_tokens), 0) as totalTokens, ifnull(sum(cost), 0) as cost from ai_log where create_time >= #{startDate} and create_time < date_add(curdate(), interval 1 day)
and user_id = #{userId}
group by date_format(create_time, '%Y-%m-%d') order by date asc

mapper.select:
select ifnull(sum(total_tokens), 0)
from ai_log
where user_id = #{userId}
